  v_def jsonb;
BEGIN
  INSERT INTO public.private_card_effect_catalog_v1(catalog_id,schema_version,definitions)
  VALUES ('main',1,'[]'::jsonb)
  ON CONFLICT (catalog_id) DO NOTHING;

  FOR v_def IN SELECT value FROM jsonb_array_elements(v_defs) LOOP
    IF NOT EXISTS (
      SELECT 1 FROM public.private_card_effect_catalog_v1 c
      CROSS JOIN LATERAL jsonb_array_elements(coalesce(c.definitions,'[]'::jsonb)) d(value)
      WHERE c.catalog_id='main' AND d.value->>'effectId'=v_def->>'effectId'
    ) THEN
      UPDATE public.private_card_effect_catalog_v1
      SET definitions=coalesce(definitions,'[]'::jsonb)||jsonb_build_array(v_def),updated_at=now()
      WHERE catalog_id='main';
    END IF;
  END LOOP;
END
